"""Объекты отрасли для карты: НПЗ, месторождения, СПГ, порты.
Цифры — округлённые оценки по открытым данным (компании, EIA, Energy Institute, GIIGNL), могут отличаться по годам.
t: ref (НПЗ, v — тыс. барр/сут) · field (v — условный размер для значка) · lng (v — млн т/год) · port
reg: ru, cn, in, us, eu, me, other   (для фильтра по странам)"""
O = []
def add(t, reg, n, c, y, x, v, cap, o, f, fact, st=''):
    O.append(dict(id=len(O), t=t, reg=reg, n=n, c=c, y=y, x=x, v=v, cap=cap, o=o, f=f, fact=fact, st=st))

